import math
from itertools import permutations

def largest_empty_square(sigma, n):
    best = 0
    for k in range(1, n+1):
        found = False
        for r in range(n - k + 1):
            for c in range(n - k + 1):
                empty = True
                for i in range(r, r + k):
                    if c <= sigma[i] <= c + k - 1:
                        empty = False
                        break
                if empty:
                    found = True
                    break
            if found:
                break
        if found:
            best = k
        else:
            break
    return best

# Verify the conjecture k* = floor(sqrt(n-1)) for n=2..10
print("Verifying conjecture k* = floor(sqrt(n-1)):")
for n in range(2, 11):
    conjectured = int(math.isqrt(n - 1))
    min_best = n
    for perm in permutations(range(n)):
        k = largest_empty_square(perm, n)
        if k < min_best:
            min_best = k
    match = "✓" if min_best == conjectured else "✗"
    print(f"  n={n}: k*={min_best}, conjectured={conjectured} {match}")

# For larger n, try to construct permutations with no empty (k+1)x(k+1) square
# where k = floor(sqrt(n-1)), i.e., m = k+1 = ceil(sqrt(n))
print("\nLooking for permutations with no empty m×m square (m = ceil(sqrt(n))):")

def has_empty_square(sigma, n, m):
    """Check if permutation has an empty m×m contiguous sub-square."""
    for r in range(n - m + 1):
        for c in range(n - m + 1):
            empty = True
            for i in range(r, r + m):
                if c <= sigma[i] <= c + m - 1:
                    empty = False
                    break
            if empty:
                return True, (r, c)
    return False, None

# Try column-major construction for n = m^2
for m in range(2, 6):
    n = m * m
    # Column-major: sigma(i*m + j) = j*m + i
    sigma = [0] * n
    for i in range(m):
        for j in range(m):
            sigma[i * m + j] = j * m + i
    has_empty, pos = has_empty_square(sigma, n, m)
    k = int(math.isqrt(n - 1))
    print(f"  n={n} (m={m}), column-major: has_empty_{m}x{m}={has_empty}, k* should be {k}")
    if has_empty:
        print(f"    Empty square at {pos}")

