import math
import random

def has_empty_square(sigma, n, m):
    for r in range(n - m + 1):
        for c in range(n - m + 1):
            empty = True
            for i in range(r, r + m):
                if c <= sigma[i] <= c + m - 1:
                    empty = False
                    break
            if empty:
                return True, (r, c)
    return False, None

# For general n with m = ceil(sqrt(n)), try to find a permutation with no empty m×m square
# Try various constructions

def try_constructions(n):
    m = math.ceil(math.sqrt(n))
    k = int(math.isqrt(n - 1))
    assert k == m - 1, f"n={n}: k={k}, m={m}, expected k=m-1"

    results = []

    # Construction 1: Column-major on m×m grid, take first n entries
    # But need it to be a permutation of {0,...,n-1}
    # Idea: fill an m×m grid with 0..m^2-1, read column by column, 
    # then "compress" to {0,...,n-1} by relabeling
    # Actually, let's try: place rook at (i, sigma(i)) where we use the 
    # column-major pattern but restricted to n cells

    # Construction 2: "Block transpose"
    # Divide rows into blocks of size m, columns into blocks of size m
    # Within the grid, transpose

    # Construction 3: sigma(i) = (i * m) mod n if gcd(m, n) == 1
    from math import gcd
    if gcd(m, n) == 1:
        sigma = [(i * m) % n for i in range(n)]
        if len(set(sigma)) == n:
            has_empty, pos = has_empty_square(sigma, n, m)
            results.append(("mult_mod", sigma, not has_empty))

    # Construction 4: Try the "grid transpose" approach
    # Write 0..n-1 in a grid with m columns, row by row
    # Then read column by column
    nrows = math.ceil(n / m)
    grid = []
    for i in range(nrows):
        row = []
        for j in range(m):
            val = i * m + j
            if val < n:
                row.append(val)
            else:
                row.append(None)
        grid.append(row)

    # Read column by column
    sigma = []
    for j in range(m):
        for i in range(nrows):
            if grid[i][j] is not None:
                sigma.append(grid[i][j])

    if len(set(sigma)) == n and len(sigma) == n:
        has_empty, pos = has_empty_square(sigma, n, m)
        results.append(("grid_transpose", sigma[:], not has_empty))

    # Construction 5: Reverse grid transpose - write column by column, read row by row
    sigma2 = [0] * n
    idx = 0
    for j in range(m):
        for i in range(nrows):
            val = i * m + j
            if val < n:
                sigma2[val] = idx
                idx += 1

    if len(set(sigma2)) == n:
        has_empty, pos = has_empty_square(sigma2, n, m)
        results.append(("reverse_grid_transpose", sigma2[:], not has_empty))

    # Construction 6: Random search
    best_sigma = None
    for _ in range(10000):
        perm = list(range(n))
        random.shuffle(perm)
        has_empty, pos = has_empty_square(perm, n, m)
        if not has_empty:
            best_sigma = perm[:]
            break
    if best_sigma:
        results.append(("random", best_sigma, True))

    return m, k, results

for n in range(2, 27):
    m, k, results = try_constructions(n)
    found = any(r[2] for r in results)
    methods = [r[0] for r in results if r[2]]
    print(f"n={n}, m={m}, k={k}: found no-empty-{m}x{m} = {found}, methods={methods}")
    if not found:
        print(f"  *** FAILED to find construction for n={n}!")

